def process(load_fire_data) -> pd.DataFrame:
    df = load_fire_data.copy()

    # Group by start_year and calculate mean start_day_of_year
    yearly_mean = df.groupby('start_year')['start_day_of_year'].mean().reset_index()
    yearly_mean.columns = ['year', 'mean_start_day']

    return yearly_mean.sort_values('year')
